# -*- coding: utf-8 -*-
"""지식그래프 시드 v2 — PDF·문서 원문 대조 보강 (2026-10-06)

seed_kg_v1.py(프로젝트 문서에서 만든 1차 시드)를 불러와, 에이전트 4개가 원문 PDF에서 쪽 단위로 추출한 304개 사실(kg_K*_facts.jsonl)
과 대조해 (1) 잘못된 쪽·수치를 고치고 (2) 빠진 노드·엣지를 더한 뒤 kg_nodes.csv · kg_edges.csv 를 쓴다.
각 수정·추가의 근거는 note/ref 의 [K1-031] 같은 fid(= kg_evidence.csv 의 fid)로 남긴다.

한 번만 돌리는 부트스트랩이다. CSV를 직접 고친 뒤에는 이 스크립트를 다시 돌리지 말 것(덮어쓴다 → --force 필요).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import seed_kg_v1 as s

NODES, EDGES, CUR_SRC = s.NODES, s.EDGES, s.CUR_SRC
NF = ["id", "label", "kind", "group", "tier", "scale", "status", "ref", "value", "desc"]
EF = ["src", "dst", "rel", "strength", "basis", "note", "ref"]


def upd(nid, **kw):
    for i, n in enumerate(NODES):
        if n[0] == nid:
            d = dict(zip(NF, n)); d.update(kw); NODES[i] = tuple(d[k] for k in NF); return
    raise KeyError("노드 없음: " + nid)


def app(nid, field, text, sep=" "):
    """기존 필드 뒤에 문장을 덧붙인다."""
    for n in NODES:
        if n[0] == nid:
            cur = dict(zip(NF, n))[field]
            upd(nid, **{field: (cur + sep + text) if cur else text}); return
    raise KeyError(nid)


def upe(src, dst, rel, **kw):
    for i, e in enumerate(EDGES):
        if e[0] == src and e[1] == dst and e[2] == rel:
            d = dict(zip(EF, e)); d.update(kw); EDGES[i] = tuple(d[k] for k in EF); return
    raise KeyError("엣지 없음: %s>%s(%s)" % (src, dst, rel))


def dele(src, dst, rel):
    for i, e in enumerate(EDGES):
        if e[0] == src and e[1] == dst and e[2] == rel:
            del EDGES[i]; return
    raise KeyError("엣지 없음: %s>%s(%s)" % (src, dst, rel))


N, E = s.N, s.E

