# ═══════════════════════════ E. 마무리: 정렬·검증·쓰기 ═══════════════════════════
KORDER = ["intent", "plan", "law", "data", "derived", "param", "eval"]


def tidy():
    first = {}
    for i, n in enumerate(NODES):
        first.setdefault((n[2], n[3]), i)
    idx = {n[0]: i for i, n in enumerate(NODES)}
    NODES.sort(key=lambda n: (KORDER.index(n[2]), first[(n[2], n[3])], idx[n[0]]))


if __name__ == "__main__":
    force = "--force" in sys.argv
    out = os.path.dirname(os.path.abspath(__file__))
    if os.path.exists(os.path.join(out, "kg_nodes.csv")) and not force:
        print("kg_nodes.csv가 이미 있다. CSV를 직접 고쳤다면 덮어쓰지 말 것. 정말 다시 만들려면 --force")
        sys.exit(1)
    tidy()
    s.main()
